return items.map((item) => {
  const b = item.json.body || item.json;
  const idCandidato = (b.id_candidato || b.candidate_id || '').toString().trim();
  const eleitorId = (b.eleitor_id || b.telefone || b.phone || b.email || Date.now().toString()).toString().trim();
  const mensagem = (b.mensagem || b.message || b.text || '').toString();
  const origem = (b.origem_captacao || b.origem || b.utm_source || 'whatsapp').toString();
  return {
    json: {
      id_candidato: idCandidato,
      eleitor_id: eleitorId,
      eleitor_uid: `${idCandidato}:${eleitorId}`,
      nome: b.nome || b.name || '',
      telefone: b.telefone || b.phone || '',
      email: b.email || '',
      cidade: b.cidade || '',
      bairro: b.bairro || '',
      tema_interesse: (b.tema_interesse || b.interesse || 'geral').toString().toLowerCase(),
      canal_preferido: b.canal_preferido || 'whatsapp',
      mensagem_eleitor: mensagem,
      consentimento_lgpd: !!b.consentimento_lgpd,
      origem_captacao: origem,
      metadata: b
    }
  };
});

const rows = items.map(i => i.json);
if (!rows.length) { return [{ json: { erro: 'candidato_nao_encontrado' } }]; }
const base = rows[0];
const prompts = {};
for (const row of rows) {
  if (row.agente_nome) prompts[row.agente_nome] = row.system_prompt;
}
const input = $item(0).$node['Normalizar Entrada'].json;
return [{ json: { ...input, nome_urna: base.nome_urna, perfil_markdown: base.perfil_markdown, prompt_relacionamento: prompts['Agente_Relacionamento'] || '', prompt_compliance: prompts['Agente_Compliance_2026'] || '' } }];

